local _, WFJ = ...
WFJ.Data.add("quest", {
  [86574] = { "Rifornimenti per ⟦Stonetalon=Petrartiglio⟧", "Raccogli $N1 Stonetalon Supplies dalle Pridewing Wyvern e consegnali alla locandiera Faralia.", "<Il povero corpo porta i segni di molti colpi delle viverne Pridewing. Lo zaino lì accanto è sgualcito e abbandonato, svuotato del contenuto; solo un piccolo biglietto stretto nella mano del corriere indica cosa sia andato perduto: un carico destinato alla locandiera Faralia, al ⟦Stonetalon Peak=Picco di Petrartiglio⟧.>\n\n<Probabilmente le viverne hanno portato via i fagotti di provviste per imbottirci i nidi.>", nil, nil, 0x91254c7f, 0x88cf623c, 0x25ddc985, nil, nil, "...mm" },
  [86576] = { "Ninnoli delle Furie Rosse", "Porta $N1 Glittering Sunstone a Mor'rogal.", "Oltre a spargere la loro sporcizia per tutta la ⟦Charred Vale=Valle Bruciata⟧, le arpie delle Furie Rosse raccolgono qualsiasi cosa luccicante riescano a trovare. Mi dicono che collezionano diverse pietre solari giallo oro come decorazione. Io non so che farmene di questi ninnoli, ma Mor'rogal ha detto di averle usate in passato.\n\nMentre combatti le arpie della valle, tieni gli occhi aperti per le Glittering Sunstone. Porta quelle che trovi a Mor'rogal, sulle colline sopra di noi.", nil, nil, 0x8c0d1828, 0x3c6482c9, 0x2a34d371, nil, nil, "...mm" },
  [86585] = { "Lo stendardo della caduta", "Issa lo stendardo di ⟦Ironforge=Forgiardente⟧, richiama il trogg Headsplitter e uccidilo, poi fai rapporto al capitano Granchiasso.", "La montanara caduta porta uno stendardo di ⟦Ironforge=Forgiardente⟧. Forse era in perlustrazione, o forse stava guidando una carica disperata. In ogni caso, lo stendardo è stato gettato a terra e calpestato. La montanara è stata colpita alla testa così forte da perdere l'elmo, ed è stata uccisa sul colpo da un trogg, probabilmente con una clava chiodata.\n\nIl trogg che l'ha uccisa è forse ancora nei paraggi, e di certo ricorda lo stendardo. Issare di nuovo lo stendardo di ⟦Ironforge=Forgiardente⟧ potrebbe attirarlo allo scoperto.", "Quello stendardo sembra reduce da una guerra!", "Hai trovato il corpo di Ylva? Ah, povera donna. Diceva che avrebbe dimostrato ai trogg che ⟦Ironforge=Forgiardente⟧ non sarebbe mai caduta per mano della loro razza. Era andata a cercare alcuni montanari mai tornati da una pattuglia nel territorio dei trogg. Era sempre stata troppo indipendente per essere prudente. Ora sappiamo cos'è successo.\n\nRiporterò indietro lo stendardo e mi assicurerò che venga ripulito ed esposto. Tu prendi la sua arma. Che possa servirti bene contro i trogg.", 0xe9fba8e6, 0x55701efb, 0x9ae4d6b9, 0xe66f0ce2, 0x0c4098ad, "....." },
  [86613] = { "Attrezzi da scavo", "Riporta $N1 ⟦Excavation Tools=Attrezzi da Scavo⟧ a ⟦Magmar Fellhew=Magmar Viltaglio⟧.", "Gli attrezzi dello scavo, abbandonati quando i nani sono fuggiti dai trogg, sembrano per lo più intatti. Riportarli agli scavatori aiuterà di certo il loro lavoro.", nil, nil, 0x417702d1, 0x4b1ae3e2, 0xf80c3305, nil, nil, "...mm" },
  [86614] = { "Argento delle onde", "Restituisci il fermaglio per capelli d'argento con il monogramma a chi lo ha perso.", "<Tra le cianfrusaglie da pesca sparse fra i detriti ci sono alcuni ami arrugginiti, bobine di filo rotte e un fermaglio per capelli d'argento, un po' corroso ma finemente lavorato, con il monogramma \"K.D.\">", "Ho un sacco di faccende da sbrigare oggi, puoi fare in fretta?", "Il mio fermaglio! Pensavo di averlo perso per sempre!\n\nCon un po' di lavoro tornerà a splendere. Grazie per avermelo portato! Ti ricompenserò come si deve.", 0x90b2445c, 0x1d2fd811, 0xbaa09a33, 0x46c58e1a, 0x873f10f3, "....." },
  [86667] = { "Tra le nevi", "Consegna un ⟦Jar of Snow=Barattolo di Neve⟧ a Norric Lochthane, nella sua casa sulla costa nord-occidentale del Loch.", "Il mio vecchio mentore, Norric, mi ha mandato un elementale minore con una strana richiesta. Gli serve un barattolo di neve per certe sue pratiche sciamaniche! Non so cosa ci voglia fare, ma ho imparato da tempo a non discutere i suoi metodi in fatto di magia.\n\nSto studiando gli elementali della zona, quindi non posso andare ad aiutarlo. Va' all'ingresso della galleria al ⟦South Gate Pass=Passo Meridionale⟧, dove c'è neve tutto l'anno. Raccoglila in questo barattolo di ceramica e portagliela prima che si sciolga. Il barattolo dovrebbe tenerla al fresco.", "Eh? Che cosa vuoi?", "Questo barattolo è per me?\n\nNeve! Grenhild ce l'ha fatta! Mi ha mandato la neve che le avevo chiesto!\n\nPeccato, però: speravo che venisse a trovarmi di persona.\n\nBe', in ogni caso, grazie per il tuo impegno. È un vero aiuto per il mio lavoro.", 0x7219b30d, 0xf3253110, 0x938b1d88, 0x8793ff36, 0x36e8bcbb, "....." },
  [86757] = { "Frenare l'avanzata degli orchi", "Porta $N1 Jagged Orc Sword e $N2 Curved Orc Dagger a Shandrina.", "Gli orchi si sono impadroniti della foresta orientale, e ora i loro esploratori e i loro soldati si aggirano per tutti i boschi! Per quelli come noi non è più sicuro muoversi per ⟦Ashenvale=Valtetra⟧.\n\nDobbiamo respingere gli orchi e mettere in sicurezza la foresta. Siamo riusciti a eliminare alcuni soldati ed esploratori muovendoci con cautela lungo i margini del loro accampamento.\n\nCombatti gli orchi e portami le spade seghettate e i coltelli ricurvi che usano. Mi assicurerò che le loro armi vengano recuperate e riutilizzate, così che nulla vada sprecato.", nil, nil, 0xa5ae3f5b, 0xef062d38, 0xf54c066d, nil, nil, "...mm" },
  [86758] = { "Il coltello nella piaga", "Trova e sconfiggi il crocolisco Daggerfang e riporta il coltello di Marek.", "Ti ho mai raccontato di quando per poco non ci rimettevo la mano per colpa di un crocolisco? Sono riuscito a piantargli il coltello nella mascella e me la sono filata alla svelta. Credevo di avere il coltello qui da qualche parte, ma non riesco a trovarlo.\n\nComunque, quel croco è probabilmente ancora là fuori a cacciare lungo la riva del lago. Quella bestiaccia va tolta di mezzo, se non altro per la sicurezza degli altri cacciatori.\n\nHo preso a chiamarlo Daggerfang. Se lo vedi, salutalo da parte mia! E per \"salutalo\" intendo \"infilzalo\".", "Come va la caccia?", "Ah! Ce l'hai fatta! Non avrei mai pensato che quel vecchio croco avrebbe avuto ciò che si meritava, ma così va benone!\n\nOh, ehm... sai, mi son dovuto procurare un altro coltello, ma magari quello ti porterà fortuna. Perché non te lo tieni?", 0xe00ca7df, 0x0397565f, 0x466c095b, 0x023e1b29, 0x855b32ce, "....." },
  [86776] = { "Ingredienti per la forgia", "Porta $N1 Lingotto di Bronzo a ⟦Morhan Coppertongue=Morhan Spargirame⟧.", "Thelsamar è un posto magnifico in cui vivere, ma non abbiamo tutte le comodità di ⟦Ironforge=Forgiardente⟧. Resto sempre senza bronzo! Me ne serve dell'altro, se voglio continuare a fare attrezzi, bollitori e pentole!\n\nSi vede che hai un po' di esperienza alla forgia. Pensi di potermi fondere qualche lingotto di bronzo? Ti pagherò bene!", "Le forge devono restare accese!", "Ah, che sollievo! Ora dovrei riuscire a tenere accesa la forgia. Speriamo che un giorno o l'altro arrivi un mercante a portare regolarmente il carbone in città!", 0xd4a01b9a, 0x3fc9ca9a, 0x466409ef, 0xef5d24bd, 0xde5ced06, "....." },
  [86784] = { "Rami e ossa", "Raccogli $N1 Dry Branch e portali a Eleanor Shackleton.", "La mia collega Eleanor Shackleton va fiera di viaggiare per le terre selvagge, sopravvivendo alle intemperie e ai mostri. Al momento è accampata non lontano da qui, sulle colline a ovest, e ricordo un consiglio che mi diede una volta: \"Quando pensi di avere abbastanza legna da ardere, raccogline cinque volte tanto.\"\n\nSe hai un po' di tempo libero, potresti raccogliere della legna in questo cesto e portarla al suo accampamento. Di sicuro potrebbe darti qualche consiglio sulla vita di un avventuriero errante.", "<Benvenuto/Benvenuta> al mio fuoco, <viaggiatore/viaggiatrice>.", "Altra legna da ardere? È sempre la benvenuta. Terrà al caldo queste vecchie ossa durante le notti fredde delle Radure.\n\nIo ho già una fascia per raccogliere la legna, quindi puoi pure tenerti quel cesto.", 0x9975c906, 0x1d5e65f3, 0xbc307d2c, 0x5adb408d, 0x33ffab6b, "....." },
})
